'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/datepicker/md-gb-date-picker.js';
import {DatePickerElement} from '@material/web/labs/gb/components/datepicker/date-picker-element.js';
import type {DatePickerValueDetail} from '@material/web/labs/gb/components/datepicker/date-picker-element.js';

/**
 * A Material Design date picker (docked or modal, single date or range). Wraps <md-gb-date-picker>.
 * Docs: https://material-web.dev/3.0/components/date-picker/
 */
export const MdDatePicker = createComponent({
  react: React,
  tagName: 'md-gb-date-picker',
  elementClass: DatePickerElement,
  events: {
    onCancel: 'cancel' as EventName<Event>,
    onChange: 'change' as EventName<CustomEvent<DatePickerValueDetail>>,
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onInput: 'input' as EventName<CustomEvent<DatePickerValueDetail>>,
    onOpen: 'open' as EventName<Event>,
  },
});

export type MdDatePickerProps = React.ComponentProps<typeof MdDatePicker>;
